                    pixelSize={32}
                />
                <Gtk.Box
                    orientation={Gtk.Orientation.VERTICAL}
                    valign={Gtk.Align.CENTER}
                >
                    <Gtk.Label
                        cssClasses={['title-2']}
                        halign={Gtk.Align.START}
                        label={preview}
                    />
                    <Gtk.Label
                        halign={Gtk.Align.START}
                        label={`ID: ${item.id}`}
                        cssClasses={['caption']}
                    />
                </Gtk.Box>
            </Gtk.Box>
        </Gtk.Button>
    );
};

